import { parseTextured, parseAnimated } from 'granny-ro-js'
import { packModel } from './src/subsystems/gr2/mesh-pack.js'
import { readFileSync } from 'node:fs'
const load = p => new Uint8Array(readFileSync(p))
const box = 'files/grf/data/model/3dmob/treasurebox_2.gr2'

const m = parseTextured(load(box))
const mesh = m.meshes[0]
console.log('mesh materials:', JSON.stringify(mesh.materials, (k,v)=> k==='textureFile'||k==='name'?v:(typeof v==='object'&&v!==null&&k!==''&&!Array.isArray(v)?'[obj]':v)))
