const skelBones = new Set(m.skeletons[0].bones.map(b=>b.name))
for (const [label,p] of [['2_dead','files/grf/data/model/3dmob_bone/2_dead.gr2'],['2_damage','files/grf/data/model/3dmob_bone/2_damage.gr2']]) {
  const b = parseAnimated(load(p))
  const a = b.animations[0]
  const trackNames = []
  for (const g of (a.trackGroups||a.transformTrackGroups||[])) for (const t of (g.transformTracks||g.tracks||[])) trackNames.push(t.name)
  const hit = trackNames.filter(n=>skelBones.has(n)).length
  console.log(label+': tracks='+trackNames.length+' matchMainSkeleton='+hit+' sample='+JSON.stringify(trackNames.slice(0,4)))
}
